window.AUTH=window.AUTH||{};window.AUTH["17-312"]={"d":"17-312","id":"2017/17-312","n":"United States v. Sanchez-Gomez","briefs":[{"k":"petitioner","label":"Brief of petitioner United States","date":"2018-01-22","url":"https://www.supremecourt.gov/DocketPDF/17/17-312/28798/20180122182804051_17-312%20Sanchez-Gomez.8.pdf","side":"pet","n":67},{"k":"respondent","label":"Brief of respondents Moises Patricio-Guzman, et al.","date":"2018-02-21","url":"https://www.supremecourt.gov/DocketPDF/17/17-312/36154/20180221165432571_Merits%20brief-Sanchez-Gomez%20Brief-Appendix.pdf","side":"res","n":64},{"k":"reply","label":"Reply of petitioner United States","date":"2018-03-14","url":"https://www.supremecourt.gov/DocketPDF/17/17-312/38876/20180314113714870_17-312rbUnitedStates.pdf","side":"pet","n":37}],"opinion":null,"tr":true,"items":[{"t":"case","label":"Abney v. United States","cite":"431 U.S. 651","y":1977,"id":"1976/75-6521","sc":1,"sum":"Petitioners and others were charged in a single-count indictment with conspiracy and an attempt to obstruct interstate commerce by means of extortion, in violation of the Hobbs Act. Petitioners challenged the indictment as duplicitous, contending that its single count improperly charged both a conspiracy and an attempt to violate the Hobbs Act. The District Court refused to dismiss the indictment but required the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"20, 22","1":"20, 25, 36, 38, 39","2":"8, 9, 10"}},{"t":"case","label":"Bell v. Wolfish","cite":"441 U.S. 520","y":1979,"id":"1978/77-1829","sc":1,"sum":"The Court found that that the conditions of confinement did not infringe upon a pretrial detainee's rights. Justice Rehnquist's opinion argued that the issue of prison management is ripe with \"judgment calls\" which rest outside the jurisdiction of the judiciary.","sumSrc":"Oyez","by":{"0":"25, 29","1":"16","2":"8"}},{"t":"case","label":"(III) Cases—Continued: Berman v. United States","cite":"302 U.S. 211","y":1937,"id":"scdb/1937-024","sc":1,"sum":"1. The sentence in a criminal case is the final judgment.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"19"}},{"t":"case","label":"Board of Sch. Comm’rs v. Jacobs","cite":"420 U.S. 128","y":1975,"id":"1974/73-1347","sc":1,"sum":"A purported class action by six named plaintiffs, who at the time were high school students, challenging the constitutionality of certain school rules and regulations, is moot, where all six have graduated from school and the District Court neither properly certified the class action under Fed. Rule Civ. Proc. 23 (c) (1) nor properly identified the class under Rule 23 (c) (3). 490 F. 2d 601, vacated and remanded.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"37, 38"}},{"t":"case","label":"Campbell-Ewald Co. v. Gomez","cite":"136 S. Ct. 663","y":2016,"id":"2015/14-857","sc":1,"sum":"The Court held that an unaccepted settlement offer does not make a plaintiff’s claim moot, and a federal contractor does not have derivative sovereign liability from a suit under the Telephone Consumer Protection Act.","sumSrc":"Oyez","by":{"0":"31","2":"17"}},{"t":"case","label":"Cheney v. United States Dist. Court","cite":"542 U.S. 367","y":2004,"id":"2003/03-475","sc":1,"ar":1,"sum":"The Court sent the case back to the D.C. Court of Appeals, arguing that the appellate court should have considered separation-of-powers claims and was wrong to conclude it lacked authority to order District Court discovery to stop.","sumSrc":"Oyez","by":{"0":"14, 15, 27, 28, 29, 30","1":"passim","2":"11, 12, 15"}},{"t":"case","label":"City of Los Angeles v. Lyons","cite":"461 U.S. 95","y":1983,"id":"1982/81-1064","sc":1,"sum":"In a 5-to-4 decision, the Court held that federal courts were without jurisdiction to entertain Lyons' claim for injunctive relief.","sumSrc":"Oyez","by":{"0":"40"}},{"t":"case","label":"Cobbledick v. United States","cite":"309 U.S. 323","y":1940,"id":"scdb/1939-076","sc":1,"sum":"An order of the District Court denying a motion to quash a subpoena duces tecum requiring one to appear with papers and testify before a grand jury is not a \"final decision\" within the meaning of Jud. Code § 128 (a). Pp. 324, 330. 107 F. 2d 975, affirmed. CERTIORARI, 308 U. S. 547, to review judgments dismissing, for want of jurisdiction, appeals from orders denying motions to quash subpoenas duces tecum. Mr. Donald …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"18","2":"7, 10"}},{"t":"case","label":"Cohen v. Beneficial Indus. Loan Corp.","cite":"337 U.S. 541","y":1949,"id":"scdb/1948-101","sc":1,"ar":1,"sum":"1. Under 28 U. S. C. § 1291, appeal may be. taken from an order of a Federal District Court denying a corporation's motion that the plaintiff in a stockholder's derivative action be required, pursuant to a state statute, to give security for reasonable expenses of the defendants, in connection with the action.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"19","1":"20, 32, 36, 38"}},{"t":"case","label":"Coopers & Lybrand v. Livesay","cite":"437 U.S. 463","y":1978,"id":"1977/76-1836","sc":1,"sum":"Respondents, who had purchased securities in reliance on a prospectus, brought this action on behalf of themselves and a class of similarly situated purchasers, alleging that petitioner accounting firm had violated the federal securities laws. The District Court first certified the action as a class action under Fed. Rule Civ. Proc. 23, and then, after further proceedings, decertified the class. Respondents then …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"20, 21","1":"20","2":"3, 7"}},{"t":"case","label":"County of Riverside v. McLaughlin","cite":"500 U.S. 44","y":1991,"id":"1990/89-1817","sc":1,"sum":"The Court held that Riverside's actions did not comply with the Gerstein precedent. Justice O'Connor argued that it was the state's burden to demonstrate extraordinary circumstances when delaying probable cause determinations beyond 48 hours. The lower court in this case had placed that responsibility on the accused. Intervening weekends or complicated pretrial proceedings were not legitimate reasons for delay.","sumSrc":"Oyez","by":{"0":"24, 29, 35, 38"}},{"t":"case","label":"De Abadia-Peixoto v. United States Dep’t of Homeland Sec.","cite":"277 F.R.D. 572","y":2011,"court":"N.D. Cal.","url":"https://www.courtlistener.com/c/F.R.D./277/572/","by":{"0":"25"}},{"t":"case","label":"Deck v. Missouri","cite":"544 U.S. 622","y":2005,"id":"2004/04-5293","sc":1,"ar":6,"sum":"Justice Stephen Breyer delivered the Court's 7-2 holding that the Constitution forbids the use of visible shackles during both a capital trial's guilt and penalty phases, unless such shackling is justified by an essential state interest specific to the defendant on trial (such as courtroom security).","sumSrc":"Oyez","by":{"0":"11, 21, 28, 29","1":"passim","2":"3, 4, 13"}},{"t":"case","label":"DeFunis v. Odegaard","cite":"416 U.S. 312","y":1974,"id":"1973/73-235","sc":1,"sum":"In a 5-4 per curiam opinion, the Court held that because the University of Washington Law School had agreed to allow DeFunis to enroll and to earn a diploma, the case in question was moot. DeFunis would be able to complete his legal studies irrespective of any Supreme Court decision.","sumSrc":"Oyez","by":{"0":"32"}},{"t":"case","label":"Estelle v. Williams","cite":"425 U.S. 501","y":1976,"id":"1975/74-676","sc":1,"sum":"Although the State cannot, consistent with the Fourteenth Amendment, compel an accused to stand trial before a jury while dressed in identifiable prison clothes, the failure to make an objection to the court as to being tried in such clothes negates the presence of the compulsion necessary to establish a constitutional violation. Nothing in the record here warrants a conclusion that respondent was compelled to stand …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"28","2":"3"}},{"t":"case","label":"Flanagan v. United States","cite":"465 U.S. 259","y":1984,"id":"1983/82-374","sc":1,"sum":"The disqualification order was not immediately appealable under § 1291, and hence the Court of Appeals had no jurisdiction to review the order prior to entry of final judgment in the case.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"passim","1":"37","2":"3, 4, 6"}},{"t":"case","label":"Florence v. Board of Chosen Freeholders","cite":"566 U.S. 318","y":2012,"id":"2011/10-945","sc":1,"sum":"The Court held that prisons that conduct suspicion-less strip searches on incoming inmates do not violate the prisoner's Fourth Amendment rights.","sumSrc":"Oyez","by":{"0":"25, 29","2":"8"}},{"t":"case","label":"General Tel. Co. v. Falcon","cite":"457 U.S. 147","y":1982,"id":"1981/81-574","sc":1,"sum":"The District Court erred in permitting respondent to maintain a class action on behalf of both employees who were denied promotion and applicants who were denied employment.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"37"}},{"t":"case","label":"Genesis Healthcare Corp. v. Symczyk","cite":"569 U.S. 66","y":2013,"id":"2012/11-1059","sc":1,"sum":"The Court held that a collective action suit on behalf of other \"similarly situated\" employees becomes moot when the individual claim does.","sumSrc":"Oyez","by":{"0":"35, 36"}},{"t":"case","label":"Gerstein v. Pugh","cite":"420 U.S. 103","y":1975,"id":"1973/73-477","sc":1,"ar":3,"sum":"The Court held that the Fourth Amendment entitles a person arrested without a warrant and charged by information to a timely preliminary hearing on probable cause.","sumSrc":"Oyez","by":{"0":"passim","1":"12, 58"}},{"t":"case","label":"Gunn v. Minton","cite":"568 U.S. 251","y":2013,"id":"2012/11-1118","sc":1,"sum":"The Court found that even though federal courts have exclusive jurisdiction over patent law cases, state courts can still hear cases related to patent law as long as that it is not the primary issue.","sumSrc":"Oyez","by":{"0":"16"}},{"t":"case","label":"Helstoski v. Meanor","cite":"442 U.S. 500","y":1979,"id":"1978/78-546","sc":1,"sum":"Mandamus was not the appropriate means of challenging the validity of the indictment on the ground that it violated the Speech or Debate Clause. Direct appeal to the Court of Appeals was available and was the proper course.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"20, 22","1":"20, 25","2":"8, 9"}},{"t":"case","label":"Honig v. Doe","cite":"484 U.S. 305","y":1988,"id":"1987/86-728","sc":1,"ar":1,"sum":"The Supreme Court, in an opinion by Justice William J. Brennan, held that since the Act covered individuals from ages 3 to 21, the claim of a 24-year-old who was no longer in school was moot, but that the claim of a 20-year-old was not moot.","sumSrc":"Oyez","by":{"0":"42","1":"49, 53, 54, 56","2":"19, 20, 21"}},{"t":"case","label":"Kingdomware Techs., Inc. v. United States","cite":"136 S. Ct. 1969","y":2016,"id":"2015/14-916","sc":1,"sum":"The Court determined that the Court had jurisdiction to address the merits of the case even if the contracts had already been performed, and the Department of Veterans Affairs’ “set-aside” for veteran-owned businesses is mandatory.","sumSrc":"Oyez","by":{"0":"41, 43","1":"55, 56"}},{"t":"case","label":"Kokkonen v. Guardian Life Ins. Co. of Am.","cite":"511 U.S. 375","y":1994,"id":"1993/93-263","sc":1,"sum":"A federal district court, possessing only that power authorized by Constitution and statute, lacks jurisdiction over a claim for breach of a contract, part of the consideration for which was dismissal of an earlier federal suit. No federal statute makes that connection (if it constitutionally could) the basis for federal-court jurisdiction over the contract dispute. Moreover, the doctrine of ancillary jurisdiction …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"16"}},{"t":"case","label":"Kremens v. Bartley","cite":"431 U.S. 119","y":1977,"id":"1976/75-1064","sc":1,"sum":"Appellees, five mentally ill individuals who were between 15 and 18 years old at the time the complaint was filed, were the named plaintiffs m an action challenging the constitutionality of a 1966 Pennsylvania statute governing the voluntary admission and voluntary commitment to state mental health institutions of persons aged 18 or younger. Appellees sought to vindicate their constitutional rights and to represent …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"37"}},{"t":"case","label":"Lane v. Williams","cite":"455 U.S. 624","y":1982,"id":"1981/80-1240","sc":1,"ar":2,"sum":"Respondents' claims for relief are moot. Assuming that the failure to advise respondents of the mandatory parole requirement rendered their guilty pleas void, they could have sought to have their convictions set aside and to plead anew, and this case would not then be moot. Such relief would free them from all consequences flowing from their convictions as well as subject them to reconviction with a possibly greater …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"42","1":"57","2":"18, 19"}},{"t":"case","label":"Lewis v. Continental Bank Corp.","cite":"494 U.S. 472","y":1990,"id":"1989/87-1955","sc":1,"sum":"Before 1987, the Bank Holding Company Act of 1956 (BHCA) allowed States to prohibit an out-of-state bank holding company from owning an in-state \"bank,\" which was defined to include an institution that both accepted demand deposits and engaged in the commercial lending business. In 1981, appellee, an Illinois bank holding company, applied to Florida to establish and operate an \"industrial savings bank\" (ISB) in that …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"31","2":"17"}},{"t":"case","label":"Midland Asphalt Corp. v. United States","cite":"489 U.S. 794","y":1989,"id":"1988/87-1905","sc":1,"sum":"A district court order denying a defendant's motion to dismiss an indictment for an alleged violation of Rule 6(e) is not immediately appealable under § 1291. Since petitioners have not yet been sentenced, the District Court's order is not a final judgment ending the litigation on the merits. Moreover, whatever view is taken of the scope of Mechanik (an issue not resolved here), an order such as that at issue does …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"19, 20, 21, 22","2":"5"}},{"t":"case","label":"Mohawk Indus., Inc. v. Carpenter","cite":"558 U.S. 100","y":2009,"id":"2009/08-678","sc":1,"sum":"The Court held that disclosure orders adverse to attorney-client privilege do not qualify for immediate appeal under the collateral order doctrine.","sumSrc":"Oyez","by":{"0":"24, 26","1":"passim"}},{"t":"case","label":"Murphy v. Hunt","cite":"455 U.S. 478","y":1982,"id":"1981/80-2165","sc":1,"sum":"Appellee's constitutional claim became moot following his state-court convictions. A favorable decision on his claim to pretrialbail would not have entitled him to bail once he was convicted. And he did not pray for damages or seek to represent a class of pretrial detainees in his federalcourt action. Nor does this case fall within the \"capable of repetition, yet evading review\" exception to the general rule of …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"40"}},{"t":"case","label":"O’Shea v. Littleton","cite":"414 U.S. 488","y":1973,"id":"1973/72-953","sc":1,"sum":"Respondents, 17 black and two white residents of Cairo, Illinois, brought a civil rights class action against petitioners, a magistrate and a circuit court jfidge, who allegedly engaged under'color of state law, in a continuing pattern and practice of conduct consisting of illegal bond-setting, sentencing, and jury-fee practices in criminal cases, which assertedly deprived respondents and members of their class of …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"41, 42","1":"56","2":"18"}},{"t":"case","label":"Parr v. United States","cite":"351 U.S. 513","y":1956,"id":"1955/320","sc":1,"sum":"1. Petitioner was indicted in one division of ther Federal District Court for the Southern District of Texas, and tlat Court granted his motion to transfer the case to another division, on the ground that local prejudice would prevent a fair trial in the division where he,was indicted. Subsequently, the Govetnment obtained a new indictment in another district for the sameoffenses and moved in the first court for …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"30","2":"14"}},{"t":"case","label":"Pasadena City Bd. of Educ. v. Spangler","cite":"427 U.S. 424","y":1976,"id":"1975/75-164","sc":1,"sum":"In 1968, respondents, Pasadena, Cal., high school students and their parents, brought a purported class action against various school officials seeking injunctive relief from allegedly unconstitutional segregation of the public schools in Pasadena. The United States intervened as a party plaintiff pursuant to § 902 of the Civil Rights Act of 1964, which provides that upon intervention \"the United States shall be …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"38, 39","1":"58"}},{"t":"case","label":"Press-Enter. Co. v. Superior Court","cite":"478 U.S. 1","y":1986,"id":"1985/84-1560","sc":1,"sum":"The Supreme Court held that the First Amendment right of public access applies to preliminary hearings. Closed preliminary hearings are only permissible when specific findings on the record show that closure is essential.","sumSrc":"Oyez","by":{"0":"41, 43","1":"55, 56"}},{"t":"case","label":"Roche v. Evaporated Milk Ass’n","cite":"319 U.S. 21","y":1943,"id":"scdb/1942-071","sc":1,"sum":"1. The Circuit Court of Appeals is empowered by § 262 of theJudicial..Code to issue all writs, not specifically provided for by statute, which may be necessary for the exercise of its jurisdiction, agreeably to the usages and principles of law.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"30"}},{"t":"case","label":"Roe v. Wade","cite":"410 U.S. 113","y":1973,"id":"1971/70-18","sc":1,"sum":"A case in which the Court struck down several Texas laws that criminalized abortion, holding that laws that impose an undue burden on a woman’s right to seek an abortion violate her fundamental right to privacy under the Due Process Clause of the Fourteenth Amendment.","sumSrc":"Oyez","by":{"0":"41, 43","1":"55, 56"}},{"t":"case","label":"Schall v. Martin","cite":"467 U.S. 253","y":1984,"id":"1983/82-1248","sc":1,"sum":"Held that pretrial detention of juveniles does not violate the right of Due Process. The pretrial detention serves the legitimate purpose of protecting both the state and the juvenile from further crimes.","sumSrc":"Oyez","by":{"0":"38"}},{"t":"case","label":"Sell v. United States","cite":"539 U.S. 166","y":2003,"id":"2002/02-5664","sc":1,"ar":3,"sum":"The Court held that the Constitution allows the Federal Government to administer antipsychotic drugs, even against the defendant's will, in limited circumstances.","sumSrc":"Oyez","by":{"0":"22","1":"20, 22, 23, 25, 32, 36","2":"8, 10"}},{"t":"case","label":"Smith v. Bayer Corp.","cite":"564 U.S. 299","y":2011,"id":"2010/09-1205","sc":1,"sum":"The Court held that the federal court exceeded its authority under the relitigation exception to the Anti-Injunction Act when it prevented a group of plaintiffs from proceeding with a class-action lawsuit over a cholesterol-lowering drug.","sumSrc":"Oyez","by":{"0":"37"}},{"t":"case","label":"Sosna v. Iowa","cite":"419 U.S. 393","y":1975,"id":"1974/73-762","sc":1,"sum":"Appellant's petition for divorce was dismissed by an Iowa trial court for lack of jurisdiction because she failed to meet the Iowa statutory requirement that a petitioner in a divorce action be a resident of the State for one year preceding the filing of the petition. Appellant then brought a class action under Fed. Rule Civ. Proc. 23 in the Federal District Court against appellees State and state trial judge, …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"15, 33, 34, 35, 37, 38"}},{"t":"case","label":"Spencer v. Kemna","cite":"523 U.S. 1","y":1998,"id":"1997/96-7171","sc":1,"ar":2,"sum":"The Court held that the expiration of Spencer's sentence caused his petition to be moot because it no longer presented an Article III case or controversy. The Court concluded that once a petitioner's sentence has expired he must demonstrate a concrete and continuing injury to maintain suit.","sumSrc":"Oyez","by":{"0":"43","1":"57, 58","2":"18, 19"}},{"t":"case","label":"Stack v. Boyle","cite":"342 U.S. 1","y":1951,"id":"scdb/1951-001","sc":1,"ar":5,"sum":"Bail has not been fixed by proper methods in this case.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"20, 22","1":"20, 23, 25, 35, 38","2":"8, 9, 11"}},{"t":"case","label":"Swisher v. Brady","cite":"438 U.S. 204","y":1978,"id":"1977/77-653","sc":1,"sum":"The Double Jeopardy Clause does not prohibit Maryland officials, acting in accordance with Rule 911, from taking exceptions to a master's proposed findings. Breed v. Jones, 421 U. S. 519, distinguished.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"35, 38"}},{"t":"case","label":"Turner v. Rogers","cite":"564 U.S. 431","y":2011,"id":"2010/10-10","sc":1,"sum":"The Court held that a defendant facing incarceration for civil contempt does not have a constitutional right to a court-appointed attorney under the Due Process Clause of the Fourteenth Amendment.","sumSrc":"Oyez","by":{"0":"41, 43","1":"49, 53, 55-56, 56","2":"19, 20, 21"}},{"t":"case","label":"United States Parole Comm’n v. Geraghty","cite":"445 U.S. 388","y":1980,"id":"1979/78-572","sc":1,"sum":"An action brought on behalf of a class does not become moot upon expiration of the named plaintiff's substantive claim, even though class certification has been denied, since the proposed representative of the class retains a \"personal stake\" in obtaining class certification sufficient to assure that Art. III values are not undermined. If the appeal from denial of the class certification results in reversal of the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"36, 38","1":"58, 59"}},{"t":"case","label":"United States v. Hollywood Motor Car Co.","cite":"458 U.S. 263","y":1982,"id":"1981/81-1144","sc":1,"sum":"The Court of Appeals was without jurisdiction under 28 U. S. C. § 1291 to review the District Court's interlocutory order refusing to dismiss the indictment. The policy embodied in § 1291 is inimical to piecemeal appellate review of trial court decisions that do not terminate the litigation, and this policy is at its strongest in the field of criminal law. Respondents' claim of prosecutorial vindictiveness does not …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"17, 18, 21, 26","2":"6, 10, 11"}},{"t":"case","label":"United States v. Howard","cite":"480 F.3d 1005","y":2007,"url":"https://www.courtlistener.com/c/F.3d/480/1005/","by":{"0":"3, 8, 9, 29","2":"12, 13"}},{"t":"case","label":"United States v. MacDonald","cite":"435 U.S. 850","y":1978,"id":"1977/75-1892","sc":1,"sum":"A defendant may not, before trial, appeal a federal district court's order denying his motion to dismiss an indictment because of an alleged violation of his Sixth Amendment right to a speedy trial. Pp. 853-863. 531 F. 2d 196, reversed and remanded.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21, 23, 25, 26","2":"6, 10"}},{"t":"case","label":"United States v. Zuber","cite":"118 F.3d 101","y":1997,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/118/101/","ar":1,"sum":"Reasoning that a district judge in a nonjury proceeding may, “without further inquiry,” elect to “defer to the professional judgment of the Marshals Service regarding the precautions that seem appropriate or necessary in the circumstances”.","sumSrc":"brief:0","by":{"0":"3","1":"13, 21, 41"}},{"t":"case","label":"Weinstein v. Bradford","cite":"423 U.S. 147","y":1975,"id":"1975/74-1287","sc":1,"sum":"Where respondent was paroled after the Court of Appeals upheld his claim in his action against petitioner parole board members that he was constitutionally entitled to certain procedural rights in connection with petitioners' consideration of his eligibility for parole, the case is moot and does not present an issue \"capable of repetition, yet evading review,\" since the action is not a class action and there is no …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"43"}},{"t":"case","label":"Will v. United States","cite":"389 U.S. 90","y":1967,"id":"1967/36","sc":1,"sum":"The record in this case discloses no proper justification for the Court of Appeals to have invoked the extraordinary writ of mandamus to review the trial court's interlocutory order.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"12, 29, 30","1":"42, 43, 44","2":"11, 13, 14, 15"}},{"t":"const","label":"Amendment IV","clauses":[["fourth-amendment","Fourth Amendment"]],"text":"The right of the people to be secure in their persons, houses, papers, and effects, against unreasonable searches and seizures, shall not be violated, and no Warrants shall issue, but upon probable cause, supported by Oath or affirmation, and particularly describing the place to be searched, and the persons or things to be seized.","by":{"0":"34"}},{"t":"const","label":"Amendment V","clauses":[["grand-jury","Grand Jury Clause"],["double-jeopardy","Double Jeopardy Clause"],["self-incrimination","Self-Incrimination Clause"],["due-process-5","Due Process Clause (Fifth Amendment)"],["takings","Takings Clause"]],"text":"No person shall be held to answer for a capital, or otherwise infamous crime, unless on a presentment or indictment of a Grand Jury, except in cases arising in the land or naval forces, or in the Militia, when in actual service in time of War or public danger; nor shall any person be subject for the same offence to be twice put in jeopardy of life or limb; nor shall be compelled in any criminal case to be a witness against himself, nor be deprived of life, liberty, or property, without due process of law; nor shall private property be taken for public use, without just compensation.","by":{"0":"35"}},{"t":"usc","label":"28 U.S.C. § 1651","url":"https://www.law.cornell.edu/uscode/text/28/1651","subs":["(a)"],"stext":{"head":"§1651. Writs","paras":[[0,"(a) The Supreme Court and all courts established by Act of Congress may issue all writs necessary or appropriate in aid of their respective jurisdictions and agreeable to the usages and principles of law."],[0,"(b) An alternative writ or rule nisi may be issued by a justice or judge of a court which has jurisdiction."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1651?type=usc&year=mostrecent&link-type=html"},"head":"§1651. Writs","tname":"Judiciary and Judicial Procedure","by":{"0":"2, 10, 14, 27","1":"39","2":"11"}},{"t":"usc","label":"8 U.S.C. § 1325","url":"https://www.law.cornell.edu/uscode/text/8/1325","by":{"0":"8"}},{"t":"usc","label":"18 U.S.C. § 875","url":"https://www.law.cornell.edu/uscode/text/18/875","subs":["(c)"],"by":{"0":"8"}},{"t":"usc","label":"18 U.S.C. § 1544","url":"https://www.law.cornell.edu/uscode/text/18/1544","by":{"0":"8"}},{"t":"usc","label":"18 U.S.C. § 3145","url":"https://www.law.cornell.edu/uscode/text/18/3145","subs":["(c)"],"by":{"0":"18"}},{"t":"usc","label":"18 U.S.C. § 3731","url":"https://www.law.cornell.edu/uscode/text/18/3731","by":{"0":"18"}},{"t":"usc","label":"18 U.S.C. § 3742","url":"https://www.law.cornell.edu/uscode/text/18/3742","by":{"0":"18"}},{"t":"usc","label":"21 U.S.C. § 952","url":"https://www.law.cornell.edu/uscode/text/21/952","by":{"0":"8"}},{"t":"usc","label":"21 U.S.C. § 960","url":"https://www.law.cornell.edu/uscode/text/21/960","by":{"0":"8"}},{"t":"usc","label":"28 U.S.C. § 566","url":"https://www.law.cornell.edu/uscode/text/28/566","subs":["(a)","(i)"],"by":{"0":"2, 2"}},{"t":"usc","label":"28 U.S.C. § 1291","url":"https://www.law.cornell.edu/uscode/text/28/1291","stext":{"head":"§1291. Final decisions of district courts","paras":[[0,"The courts of appeals (other than the United States Court of Appeals for the Federal Circuit) shall have jurisdiction of appeals from all final decisions of the district courts of the United States, the United States District Court for the District of the Canal Zone, the District Court of Guam, and the District Court of the Virgin Islands, except where a direct review may be had in the Supreme Court. The jurisdiction of the United States Court of Appeals for the Federal Circuit shall be limited to the jurisdiction described in sections 1292(c) and (d) and 1295 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1291?type=usc&year=mostrecent&link-type=html"},"ar":1,"head":"§1291. Final decisions of district courts","tname":"Judiciary and Judicial Procedure","by":{"0":"2, 13, 14, 16, 17, 20","1":"19","2":"3"}},{"t":"rule","label":"Fed. R. Crim. P. 16","url":"https://www.law.cornell.edu/rules/frcrmp/rule_16","by":{"0":"24"}},{"t":"case","label":"Ashcroft v. Iqbal","cite":"556 U.S. 662","y":2009,"id":"2008/07-1015","sc":1,"sum":"The Court found that high-ranking government officials were not liable for unconstitutional acts by subordinate officials.","sumSrc":"Oyez","by":{"1":"19, 20"}},{"t":"case","label":"Atl. Marine Constr. Co. v. U.S. Dist. Court","cite":"134 S. Ct. 568","y":2013,"url":"https://www.courtlistener.com/c/S.%20Ct./134/568/","sc":1,"by":{"1":"47, 48"}},{"t":"case","label":"Burlington N.R.R. Co. v. Bhd. of Maint. of Way Emps.","cite":"481 U.S. 429","y":1987,"id":"1986/86-39","sc":1,"sum":"The Court held that Congress passed the Norris-LaGuardia Act expressly to prevent courts from distinguishing between primary and secondary actors for the purposes of labor immunity in labor disputes.","sumSrc":"Oyez","by":{"1":"55"}},{"t":"case","label":"Colgrove v. Battin","cite":"413 U.S. 149","y":1973,"id":"1972/71-1442","sc":1,"sum":"Local federal court rule providing that a jury for the trial of civil cases shall consist of six persons comports with the Seventh Amendment requirement and the coextensive statutory requirement of 28 U. S. C. § 2072 that the right of trial by jury be preserved in suits at common law, and is not inconsistent with Fed. Rule Civ. Proc. 48 that deals only with parties' stipulations regarding jury size. Pp. 151-164. 456 …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"48"}},{"t":"case","label":"Dig. Equip. Corp. v. Desktop Direct","cite":"511 U.S. 863","y":1994,"id":"1993/93-405","sc":1,"sum":"The Supreme Court ruled that the denial of immunity - while cause for concern - does not automatically create a right to immediate appeal. It is important to have final judgments before appeals are made, Justice David H. Souter wrote for the Court, and exceptions should only be made in particularly important cases.","sumSrc":"Oyez","by":{"1":"19, 33"}},{"t":"case","label":"Foley v. Blair & Co.","cite":"414 U.S. 212","y":1973,"id":"1973/72-1154","sc":1,"sum":"Where the issue of whether the confirmation of the Chapter XI arrangement renders the case moot because the petitioners no longer have a monetary stake in resolving whether the fifth act of bankruptcy had been committed, was briefed and argued before this Court, but because of the sequence of events was necessarily not treated in the Court of Appeals' opinion, the Court of Appeals should have the opportunity to …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"52"}},{"t":"case","label":"Golden v. Zwickler","cite":"394 U.S. 103","y":1969,"id":"1968/370","sc":1,"sum":"Following reversal on state law grounds of appellee's conviction of violating a New York statute by distributing anonymous handbills in connection with the 1964 congressional election, appellee in 1966 sought a declaratory judgment in the District Court that the statute was unconstitutional. Appellee alleged that he intended to distribute the 1964 handbill and \"similar anonymous leaflets\" in connection with the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"56"}},{"t":"case","label":"Greenholtz v. Neb. Penal Inmates","cite":"442 U.S. 1","y":1979,"id":"1978/78-201","sc":1,"sum":"The Court held that, although there is no constitutional right to an inmate’s release from prison prior to the expiration of a valid sentence, the specific wording of the Nebraska statute created a constitutionally protected expectation of parole.","sumSrc":"Oyez","by":{"1":"26"}},{"t":"case","label":"Hamdi v. Rumsfeld","cite":"542 U.S. 507","y":2004,"id":"2003/03-6696","sc":1,"sum":"The Court held that individuals held in military confinement by the national government have a right, under the Fifth Amendment, to appeal that confinement in front of a neutral decision-making body.","sumSrc":"Oyez","by":{"1":"27"}},{"t":"case","label":"Hollingsworth v. Perry","cite":"558 U.S. 183","y":2010,"id":"scdb/2009-018","sc":1,"sum":"Yes. The applicants showed a fair prospect that the Court would grant certiorari and reverse or grant mandamus, because the District Court likely violated 28 U.S.C. § 2071 in amending its local rule, and showed likely irreparable harm with the equities favoring them. The Court stayed the streaming to other courthouses and did not address broadcasting generally.","sumSrc":"AI-generated brief","by":{"1":"40, 45"}},{"t":"case","label":"Kerr v. U.S. Dist. Court for N. Dist.","cite":"426 U.S. 394","y":1976,"id":"1975/74-1023","sc":1,"sum":"The Court held that a writ of mandamus was inappropriate where officials associated with California state prisons system sought to prevent the production of certain documents requested by prisoners in a class action lawsuit about the sentencing and punishment of inmates.","sumSrc":"Oyez","by":{"1":"39, 42, 43"}},{"t":"case","label":"La. Buy v. Howes Leather, Co.","cite":"352 U.S. 249","y":1957,"id":"1956/27","sc":1,"sum":"The Court of Appeals properly issued the writs of mandamus.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"11, 39"}},{"t":"case","label":"Lambrix v. Singletary","cite":"520 U.S. 518","y":1997,"id":"1996/96-5658","sc":1,"sum":"Authored by Justice Antonin Scalia, the Court ruled that a prisoner whose conviction became final before the ruling, which held that if the sentencing judge in a \"weighing\" State is required to give deference to a jury's advisory sentencing recommendation, then neither the jury nor the judge is constitutionally permitted to weigh invalid aggravating circumstances, is foreclosed from relying on that decision in a federal habeas corpus proceeding.","sumSrc":"Oyez","by":{"1":"55"}},{"t":"case","label":"Mallard v. U.S. Dist. Court for S. Dist.","cite":"490 U.S. 296","y":1989,"id":"1988/87-1490","sc":1,"ar":1,"sum":"Petitioner Mallard, an attorney recently admitted to practice before the District Court, was selected to represent indigent inmates in their suit in that court against prison officials under 42 U. S. C. § 1983. After a Magistrate denied his motion to withdraw, he appealed to the District Court, contending that forcing him to represent indigent inmates in a complex action requiring trial skills he did not possess …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"42, 44, 48","2":"12, 14"}},{"t":"case","label":"MCI Telecomms. Corp. v. Credit Builders of Am., Inc.","cite":"508 U.S. 957","y":1993,"url":"https://supreme.justia.com/cases/federal/us/508/957/","sc":1,"by":{"1":"52"}},{"t":"case","label":"Mitchell v. Forsyth","cite":"472 U.S. 511","y":1985,"id":"1984/84-335","sc":1,"sum":"In 1970, petitioner, who was then the Attorney General, authorized a warrantless wiretap for the purpose of gathering intelligence regarding the activities of a radical group that had made tentative plans to take actions threatening the Nation's security. During the time the wiretap was installed, the Government intercepted three conversations between a member of the group and respondent. Thereafter, this Court in …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"22, 39"}},{"t":"case","label":"Neb. Press Ass’n v. Stuart","cite":"427 U.S. 539","y":1976,"id":"1975/75-817","sc":1,"sum":"The Court agreed with the trial judge that the murder case would generate \"intense and pervasive pretrial publicity.\" However, the unanimous court held that the practical problems associated with implementing a prior restraint on the press in this case would not have served the accused's rights.","sumSrc":"Oyez","by":{"1":"55"}},{"t":"case","label":"Platt v. Minnesota Min. & Mfg. Co.","cite":"376 U.S. 240","y":1964,"id":"1963/113","sc":1,"sum":"Respondent company, indicted for antitrust violations in an Illinois district, filed a motion to transfer the prosecution to the district of Minnesota under Rule 21 (b) of the Federal Rules of Criminal Procedure, which provides for the transfer of a multi-venue case where it would be \"in the interest of justice.\" The trial judge denied the motion, enumerating ten separate factors, including the difficulty which he …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"43"}},{"t":"case","label":"Schlagenhauf v. Holder","cite":"379 U.S. 104","y":1964,"id":"1964/8","sc":1,"ar":1,"sum":"A bus collided with the rear of a tractor-trailer and a diversity action for damages was brought by certain bus passengers in the District Court. The defendants-the bus company, petitioner its driver, the owners of the tractor and the trailer (hereinafter codefendants), and the tractor driver-filed answers denying negligence. The bus company cross-claimed against codefendants for damage to its bus, claiming that the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"33, 39, 44, 46, 47, 48","2":"15, 16"}},{"t":"case","label":"Snyder v. Massachusetts","cite":"291 U.S. 97","y":1934,"id":"scdb/1933-072","sc":1,"sum":"1. So far as the Fourteenth Amendment is concerned, the presence of the defendant in a prosecution for felony is a condition of due process to the extent that a fair and just hearing would be thwarted by his absence, and to that extent only.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"26"}},{"t":"case","label":"United States v. Allied Oil Corp.","cite":"341 U.S. 1","y":1951,"id":"scdb/1950-054","sc":1,"sum":"1. In actions brought by the Administrator under § 205 (e) of the Emergency Price Control Act of 1942 to recover damages from sellers who sold commodities at overceiling prices, which actions were pending when price controls were terminated, the substitution of the United States (rather than the Administrator's successor) as the party plaintiff was authorized by Executive Orders Nos. 9841 and 9842.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"22"}},{"t":"case","label":"United States v. Boigegrain","cite":"122 F.3d 1345","y":1997,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/122/1345/","by":{"1":"24"}},{"t":"case","label":"United States v. Davis","cite":"93 F.3d 1286","y":1996,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/93/1286/","by":{"1":"24"}},{"t":"case","label":"United States v. Ferro","cite":"321 F.3d 756","y":2003,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/321/756/","by":{"1":"24"}},{"t":"case","label":"United States v. Filippi","cite":"211 F.3d 649","y":2000,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/211/649/","by":{"1":"24"}},{"t":"case","label":"United States v. Friedman","cite":"366 F.3d 975","y":2004,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/366/975/","by":{"1":"24"}},{"t":"case","label":"United States v. Gold","cite":"790 F.2d 235","y":1986,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/790/235/","by":{"1":"24"}},{"t":"case","label":"United States v. Jicarilla Apache Nation","cite":"564 U.S. 162","y":2011,"id":"2010/10-382","sc":1,"sum":"The Court held that the fiduciary exception to the attorney-client privilege does not apply to the general trust relationship between the United States and the Indian Tribes.","sumSrc":"Oyez","by":{"1":"47"}},{"t":"case","label":"United States v. Weissberger","cite":"951 F.2d 392","y":1991,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/951/392/","by":{"1":"24"}},{"t":"case","label":"Wash. v. Glucksberg","cite":"521 U.S. 702","y":1997,"id":"1996/96-110","sc":1,"sum":"The Court decided that a law banning physician-assisted suicide does not violate the Due Process Clause of the Fourteenth Amendment.","sumSrc":"Oyez","by":{"1":"26, 27"}},{"t":"case","label":"Will v. Calvert Fire Ins. Co.","cite":"437 U.S. 655","y":1978,"id":"1977/77-693","sc":1,"sum":"The judgment is reversed. Pp. 661-667; 667-668. 560 F. 2d 792, reversed. MR. JUSTICE REHNQUIST, joined by MR. JUSTICE STEWART, MR. JUSTICE WHITE, and MR. JUSTICE STEVENS, concluded: Issuance of the writ of mandamus by the Court of Appeals impermissibly interfered with petitioner's discretion to control his docket. Pp. 661-667. …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"45"}},{"t":"case","label":"Will v. Hallock","cite":"546 U.S. 345","y":2006,"id":"2005/04-1332","sc":1,"sum":"The Court ruled that the Circuit Court had no jurisdiction to hear an appeal under the collateral order doctrine. Writing for the Court, Justice David Souter stressed the narrow scope of the doctrine. The Court reiterated that only orders that cannot be \"effectively\" reviewed after a final judgment can be appealed before the close of the trial.","sumSrc":"Oyez","by":{"1":"21, 25, 35"}},{"t":"case","label":"Youngberg v. Romeo","cite":"457 U.S. 307","y":1982,"id":"1981/80-1429","sc":1,"ar":1,"sum":"The Court held that the involuntarily committed do have liberty interests in safe confinement and freedom from bodily restraint under the Fourteenth Amendment.","sumSrc":"Oyez","by":{"1":"12, 26"}},{"t":"usc","label":"18 U.S.C. § 4241","url":"https://www.law.cornell.edu/uscode/text/18/4241","by":{"1":"24"}},{"t":"usc","label":"28 U.S.C. § 1292","url":"https://www.law.cornell.edu/uscode/text/28/1292","by":{"1":"33, 34"}},{"t":"usc","label":"28 U.S.C. § 1404","url":"https://www.law.cornell.edu/uscode/text/28/1404","by":{"1":"47, 48"}},{"t":"usc","label":"28 U.S.C. § 1915","url":"https://www.law.cornell.edu/uscode/text/28/1915","subs":["(d)"],"stext":{"head":"§1915. Proceedings in forma pauperis","paras":[[0,"(a)(1) Subject to subsection (b), any court of the United States may authorize the commencement, prosecution or defense of any suit, action or proceeding, civil or criminal, or appeal therein, without prepayment of fees or security therefor, by a person who submits an affidavit that includes a statement of all assets such prisoner possesses that the person is unable to pay such fees or give security therefor. Such affidavit shall state the nature of the action, defense or appeal and affiant's belief that the person is entitled to redress."],[0,"(2) A prisoner seeking to bring a civil action or appeal a judgment in a civil action or proceeding without prepayment of fees or security therefor, in addition to filing the affidavit filed under paragraph (1), shall submit a certified copy of the trust fund account statement (or institutional equivalent) for the prisoner for the 6-month period immediately preceding the filing of the complaint or notice of appeal, obtained from the appropriate official of each prison at which the prisoner is or was confined."],[0,"(3) An appeal may not be taken in forma pauperis if the trial court certifies in writing that it is not taken in good faith."],[0,"(b)(1) Notwithstanding subsection (a), if a prisoner brings a civil action or files an appeal in forma pauperis, the prisoner shall be required to pay the full amount of a filing fee. The court shall assess and, when funds exist, collect, as a partial payment of any court fees required by law, an initial partial filing fee of 20 percent of the greater of—"],[1,"(A) the average monthly deposits to the prisoner's account; or"],[1,"(B) the average monthly balance in the prisoner's account for the 6-month period immediately preceding the filing of the complaint or notice of appeal."],[0,"(2) After payment of the initial partial filing fee, the prisoner shall be required to make monthly payments of 20 percent of the preceding month's income credited to the prisoner's account. The agency having custody of the prisoner shall forward payments from the prisoner's account to the clerk of the court each time the amount in the account exceeds $10 until the filing fees are paid."],[0,"(3) In no event shall the filing fee collected exceed the amount of fees permitted by statute for the commencement of a civil action or an appeal of a civil action or criminal judgment."],[0,"(4) In no event shall a prisoner be prohibited from bringing a civil action or appealing a civil or criminal judgment for the reason that the prisoner has no assets and no means by which to pay the initial partial filing fee."],[0,"(c) Upon the filing of an affidavit in accordance with subsections (a) and (b) and the prepayment of any partial filing fee as may be required under subsection (b), the court may direct payment by the United States of the expenses of (1) printing the record on appeal in any civil or criminal case, if such printing is required by the appellate court; (2) preparing a transcript of proceedings before a United States magistrate judge in any civil or criminal case, if such transcript is required by the district court, in the case of proceedings conducted under section 636(b) of this title or under section 3401(b) of title 18, United States Code; and (3) printing the record on appeal if such printing is required by the appellate court, in the case of proceedings conducted pursuant to section 636(c) of this title. Such expenses shall be paid when authorized by the Director of the Administrative Office of the United States Courts."],[0,"(d) The officers of the court shall issue and serve all process, and perform all duties in such cases. Witnesses shall attend as in other cases, and the same remedies shall be available as are provided for by law in other cases."],[0,"(e)(1) The court may request an attorney to represent any person unable to afford counsel."],[0,"(2) Notwithstanding any filing fee, or any portion thereof, that may have been paid, the court shall dismiss the case at any time if the court determines that—"],[1,"(A) the allegation of poverty is untrue; or"],[1,"(B) the action or appeal—"],[2,"(i) is frivolous or malicious;"],[2,"(ii) fails to state a claim on which relief may be granted; or"],[2,"(iii) seeks monetary relief against a defendant who is immune from such relief."],[0,"(f)(1) Judgment may be rendered for costs at the conclusion of the suit or action as in other proceedings, but the United States shall not be liable for any of the costs thus incurred. If the United States has paid the cost of a stenographic transcript or printed record for the prevailing party, the same shall be taxed in favor of the United States."],[0,"(2)(A) If the judgment against a prisoner includes the payment of costs under this subsection, the prisoner shall be required to pay the full amount of the costs ordered."],[0,"(B) The prisoner shall be required to make payments for costs under this subsection in the same manner as is provided for filing fees under subsection (a)(2)."],[0,"(C) In no event shall the costs collected exceed the amount of the costs ordered by the court."],[0,"(g) In no event shall a prisoner bring a civil action or appeal a judgment in a civil action or proceeding under this section if the prisoner has, on 3 or more prior occasions, while incarcerated or detained in any facility, brought an action or appeal in a court of the United States that was dismissed on the grounds that it is frivolous, malicious, or fails to state a claim upon which relief may be granted, unless the prisoner is under imminent danger of serious physical injury."],[0,"(h) As used in this section, the term \"prisoner\" means any person incarcerated or detained in any facility who is accused of, convicted of, sentenced for, or adjudicated delinquent for, violations of criminal law or the terms and conditions of parole, probation, pretrial release, or diversionary program."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1915?type=usc&year=mostrecent&link-type=html"},"head":"§1915. Proceedings in forma pauperis","tname":"Judiciary and Judicial Procedure","by":{"1":"44, 48","2":"14"}},{"t":"rule","label":"Fed. R. Civ. P. 35","url":"https://www.law.cornell.edu/rules/frcp/rule_35","by":{"1":"46, 47, 48"}},{"t":"case","label":"Bankers Life & Cas. Co. v. Holland","cite":"346 U.S. 379","y":1953,"id":"scdb/1953-011","sc":1,"sum":"In the circumstances of this case, mandamus against a federal district judge was not an appropriate remedy to vacate a severance and transfer order entered by him under 28 U. S. C. § 1406 (a) on the ground of improper venue.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"14"}},{"t":"case","label":"Coleman v. Tollefson","cite":"135 S. Ct. 1759","y":2015,"id":"2014/13-1333","sc":1,"sum":"The Court held that a district court’s dismissal of a lawsuit counts as a “strike” for the purpose of the Prison Litigation Reform Act’s “three strikes” provision when the case is pending on appeal.","sumSrc":"Oyez","by":{"2":"14"}},{"t":"case","label":"DiBella v. United States","cite":"369 U.S. 121","y":1962,"id":"1961/21","sc":1,"sum":"An order of a Federal District Court granting or denying a pre-indictment motion under Federal Rule of Criminal Procedure 41 (e) to suppress the evidentiary use in a federal criminal trial of property allegedly procured through an unlawful search and seizure is not appealable-even when rendered in a different district from that of trial. Pp. 121-133. 284 F. 2d 897, judgment vacated with instructions to dismiss the …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"6"}},{"t":"case","label":"McKaskle v. Wiggins","cite":"465 U.S. 168","y":1984,"id":"1983/82-1135","sc":1,"sum":"The Court held that the Sixth Amendment does not guarantee the right to self-representation completely free from the presence of standby counsel.","sumSrc":"Oyez","by":{"2":"5"}},{"t":"case","label":"Rodriguez de Quijas v. Shearson/American Express, Inc.","cite":"490 U.S. 477","y":1989,"id":"1988/88-385","sc":1,"sum":"A predispute agreement to arbitrate claims under the Securities Act of 1933 is enforceable and resolution of the claims only in a judicial forum is not required.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"13"}},{"t":"case","label":"United States v. Munsingwer, Inc.","cite":"340 U.S. 36","y":1950,"id":"scdb/1950-004","sc":1,"sum":"The dismissal is sustained.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"18"}},{"t":"case","label":"Weaver v. Massachusetts","cite":"137 S. Ct. 1899","y":2017,"id":"2016/16-240","sc":1,"sum":"The Court determined that, in the context of the violation of a right to a public trial during jury selection, when the structural error was first raised via an ineffective assistance of counsel claim, the defendant must demonstrate that he suffered prejudice in order to secure a new trial.","sumSrc":"Oyez","by":{"2":"6"}}]};